INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('835879d3-d3da-4a96-b16e-05b3286113f1', '37a116c3-614a-480b-ae11-36ff59cdf800', 0, 'ClusterIP');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c73e62d3-d490-4588-a4d5-9355e796f167', '37a116c3-614a-480b-ae11-36ff59cdf800', 1, 'NodePort');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2a7335c-ccee-46e3-8f52-de6037e5053c', '37a116c3-614a-480b-ae11-36ff59cdf800', 2, 'LoadBalancer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec8ba496-900a-43f3-a5c5-8151a65325fc', '37a116c3-614a-480b-ae11-36ff59cdf800', 3, 'ExternalName');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
