INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25f2f3d9-6bc1-4c7f-9248-17ebbe825d81', '233fadad-2c76-4f01-9646-e4d57b66f453', 0, 'It returns a CNAME record pointing to an external DNS name given in spec.externalName — no proxying, selector, or cluster IP is involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bf8bf99-eaec-4843-91b9-c849decf2208', '233fadad-2c76-4f01-9646-e4d57b66f453', 1, 'It load-balances traffic across Pods running in a different cluster');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d97ba053-761e-4425-a13c-ebed46f8fda2', '233fadad-2c76-4f01-9646-e4d57b66f453', 2, 'It''s functionally identical to ClusterIP but restricted to a specific namespace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e93e7ffe-68f3-4be2-80e3-02d2a5187b0e', '233fadad-2c76-4f01-9646-e4d57b66f453', 3, 'It automatically provisions a cloud load balancer for an external endpoint');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6b3cfd2-dc03-4a99-b961-9015f2fb70f4', 'a5b1e851-27ea-4379-96d1-816715fa042d', 0, 'To route traffic to an endpoint outside normal Pod selection (e.g. an external database); you must manually create a matching Endpoints or EndpointSlice object yourself since there are no Pods to auto-populate it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f2a35aa-2014-477f-a5b0-bab098b1a0ec', 'a5b1e851-27ea-4379-96d1-816715fa042d', 1, 'It''s invalid — every Service must have a selector');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83454500-1541-4ac5-a582-3d61bd46a7cb', 'a5b1e851-27ea-4379-96d1-816715fa042d', 2, 'It automatically becomes a headless Service with no further action needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7e2f315-09ab-4792-9b6b-44a81c998683', 'a5b1e851-27ea-4379-96d1-816715fa042d', 3, 'It only works for Services of type LoadBalancer');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c41f5e90-7484-4ad8-b194-121eff1a505c', '6671b471-979e-445d-97b9-a7414985d999', 0, 'Named ports make multi-port Service/Pod specs self-documenting and let other objects reference the port by name instead of repeating raw numbers everywhere');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c31da72a-4a41-4911-a94d-6253a27c5046', '6671b471-979e-445d-97b9-a7414985d999', 1, 'Kubernetes requires named ports for any Service exposing more than one port — unnamed multi-port Services are rejected');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('304d5e3a-5b43-4fd9-8849-6dea2162b5f2', '6671b471-979e-445d-97b9-a7414985d999', 2, 'Named ports are required for TLS termination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfe07723-d26a-475a-aa2c-90ee72b05c21', '6671b471-979e-445d-97b9-a7414985d999', 3, 'Named ports let you skip specifying targetPort entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ca44d8f-38f9-4d69-a202-10ea3fddd333', '2933e12f-84f2-4d20-9c99-0658d0abd554', 0, '''port'' is the port the Service itself listens on (what clients use to reach it); ''targetPort'' is the port on the backend Pod''s container that traffic is actually forwarded to — they can differ');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('585e4d2c-7d56-4188-a553-7e71f02fe70e', '2933e12f-84f2-4d20-9c99-0658d0abd554', 1, '''port'' is for TCP and ''targetPort'' is for UDP');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47e41d44-2a02-477c-95fc-0035b55691be', '2933e12f-84f2-4d20-9c99-0658d0abd554', 2, '''targetPort'' is only used for NodePort Services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57c9bc5e-aced-4f4e-ba73-7f295d8a739e', '2933e12f-84f2-4d20-9c99-0658d0abd554', 3, 'They must always be set to the same numeric value');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c16ed5ba-0d39-432f-bab2-8de6f1630740', '9e182cd7-0cf1-4320-a1b0-82f61760ada1', 0, '30000-32767');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('878e060b-3fdd-4629-b8ed-5df8d5a7b947', '9e182cd7-0cf1-4320-a1b0-82f61760ada1', 1, '1024-2048');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3864665f-dc86-46b1-b5bb-8b2b1d6a7324', '9e182cd7-0cf1-4320-a1b0-82f61760ada1', 2, '8000-9000');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ebe6bc6-d148-4ce6-8fa3-d85fec5ea51c', '9e182cd7-0cf1-4320-a1b0-82f61760ada1', 3, '443-8443');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('539dba0f-61cc-42cd-8276-73627b8d2c47', 'd65c4622-8a48-4bf1-9c7d-3b07c5646a2a', 0, 'Routes repeated requests from the same client IP to the same backend Pod (within a timeout window), instead of the default distribution across all matching Pods');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5e8ae4a-1ab0-4499-9892-2d86c287cf82', 'd65c4622-8a48-4bf1-9c7d-3b07c5646a2a', 1, 'Restricts the Service to only accept traffic from a single, hardcoded client IP');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54da9da8-2645-420a-98cc-a11b1cd15534', 'd65c4622-8a48-4bf1-9c7d-3b07c5646a2a', 2, 'Forces all traffic through a single node''s IP');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1929dc6-f611-440e-a873-daea5721524c', 'd65c4622-8a48-4bf1-9c7d-3b07c5646a2a', 3, 'Disables load balancing entirely for that Service, functioning like a headless Service');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8caf87e2-61d2-4746-bf04-54cdba1befe8', '3e8a39b7-ddf6-4a15-8751-e713f0d13294', 0, 'The Pod is excluded from the Service''s Endpoints/EndpointSlice until it passes readiness again — traffic is not sent to a not-Ready Pod even though its labels match');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97e470d1-fb9a-4053-8f92-62cd9925e83c', '3e8a39b7-ddf6-4a15-8751-e713f0d13294', 1, 'The Service is deleted automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('459c456c-4c46-4f33-a1d8-d9921acc85a8', '3e8a39b7-ddf6-4a15-8751-e713f0d13294', 2, 'Traffic is still sent to it, since readiness only affects rolling updates, not Services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('110851f5-8cc3-4089-a34b-c03b3dd2d42f', '3e8a39b7-ddf6-4a15-8751-e713f0d13294', 3, 'The Pod is automatically restarted by the Service');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('135414fb-f3c7-4ef3-bdda-5726736d976e', '76905617-c18c-49bb-8c7c-79ea2745d12e', 0, 'A new Service (ClusterIP by default) that routes port 80 to port 8080 on the Deployment''s Pods, using the Deployment''s Pod-template labels as its selector');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff5a6916-236c-4f89-b02c-f5bc771b0f78', '76905617-c18c-49bb-8c7c-79ea2745d12e', 1, 'A new Ingress resource routing to the Deployment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dbad2d7b-7375-40d1-af18-0bb20e58efd0', '76905617-c18c-49bb-8c7c-79ea2745d12e', 2, 'A new Deployment identical to my-app but exposed publicly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78c9ad13-a620-447c-8090-10b54e9fefa8', '76905617-c18c-49bb-8c7c-79ea2745d12e', 3, 'A NetworkPolicy allowing external access to the Deployment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('423f89a9-c333-4a72-9521-0d0ae291453f', '55774a58-79b7-4339-82cb-b63b702782c3', 0, 'They''re only populated for Services that already existed at the time the consuming Pod was created — a Service created afterward won''t retroactively appear in the env vars of already-running Pods');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a2858ba-ce8a-4a52-881e-c99703b7a181', '55774a58-79b7-4339-82cb-b63b702782c3', 1, 'They only work for Services of type LoadBalancer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ede88b8a-aa42-422d-a47e-34d8d7ece17b', '55774a58-79b7-4339-82cb-b63b702782c3', 2, 'They expose the full Service YAML as JSON in a single variable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f012c50-accb-47b0-9ce8-2802b03fa846', '55774a58-79b7-4339-82cb-b63b702782c3', 3, 'They''re deprecated and no longer injected in any current Kubernetes version');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a093f05c-cc70-4cf0-a88c-d28acd9d8d33', '40cec85e-7fb5-4577-81d2-d7717be2cc47', 0, 'Temporarily forward a local port on your machine to the Service''s port for ad-hoc local access/debugging, without exposing the Service externally via NodePort/LoadBalancer/Ingress');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77edf064-eedd-4ed8-aad6-5bf78e3f69fe', '40cec85e-7fb5-4577-81d2-d7717be2cc47', 1, 'Permanently change the Service''s type to NodePort');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31422fba-c717-4842-a834-984bbbd67b79', '40cec85e-7fb5-4577-81d2-d7717be2cc47', 2, 'Create a new Ingress rule bound to port 8080');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('042f0fe3-0c65-456d-991b-14bb6035cdff', '40cec85e-7fb5-4577-81d2-d7717be2cc47', 3, 'Rewrite the Service''s selector to match a different Deployment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47bf74c2-bfa2-41c6-a8a9-af451e118967', '6b697a48-f160-4224-a1f0-18cf7b61e27f', 0, 'A more scalable way to track a Service''s backing Pod IPs/ports, splitting large endpoint sets across multiple slices rather than one unbounded Endpoints object, with support for multiple IP families and extra topology info');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('280112fc-a5ac-4aac-9f17-852074c90950', '6b697a48-f160-4224-a1f0-18cf7b61e27f', 1, 'A way to bypass kube-proxy entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ddbe491-7e26-4ee6-a534-51db4a60e009', '6b697a48-f160-4224-a1f0-18cf7b61e27f', 2, 'A new mechanism that replaces Services altogether');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dce6a1ee-28a2-4a49-87ee-eb17f4e36d1d', '6b697a48-f160-4224-a1f0-18cf7b61e27f', 3, 'A CRD that only NetworkPolicy consumes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5f09132-f41f-4b44-b974-9fedeffbbd6f', 'bd3f072c-139f-4818-95d3-bfff34e3315c', 0, 'The Service''s spec.selector key/value pairs must match labels present on the target Pods, and those Pods must expose the matching containerPort');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f421a2d-86d7-4919-8818-4ac3bc716499', 'bd3f072c-139f-4818-95d3-bfff34e3315c', 1, 'The Pods must be in a Deployment specifically — bare Pods can never be selected by a Service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d03fdf9-4c83-4efd-9122-7addaf8126ee', 'bd3f072c-139f-4818-95d3-bfff34e3315c', 2, 'The Service and Pods must share the exact same name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2c0fe1f-8602-44fd-b9b3-4a69529e6944', 'bd3f072c-139f-4818-95d3-bfff34e3315c', 3, 'The Pods must be annotated with the Service''s UID');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7243877-ced4-48dc-a7d6-7555fe3bc3f3', '8652306d-f174-411b-abd6-748b117947e7', 0, 'Host-based routing: requests are routed to different backend Services depending on the Host header, all through one Ingress controller/load balancer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e7fb848-5808-43e2-b81a-37769d7d4015', '8652306d-f174-411b-abd6-748b117947e7', 1, 'It''s invalid; an Ingress may only define one host per resource');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('771e91ee-eee8-4711-876d-510ccba97af7', '8652306d-f174-411b-abd6-748b117947e7', 2, 'Both hostnames must resolve to different Ingress controllers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('025bde12-8dff-4034-bd45-2d36a3ff9279', '8652306d-f174-411b-abd6-748b117947e7', 3, 'It creates two separate LoadBalancer Services automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5618c9ff-028e-42b2-ad60-4448df496f20', '376698cd-9fad-48ba-8517-9121ba3c9ed0', 0, 'The rule matches any request path that starts with /api (e.g. /api/users), not just the literal string /api; Exact would require the path to match precisely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67125ca8-8729-4895-98c5-dac03687928d', '376698cd-9fad-48ba-8517-9121ba3c9ed0', 1, 'Prefix means the rule only matches when the path has no trailing segments at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6080372-cd20-4d84-96b1-7718906238a2', '376698cd-9fad-48ba-8517-9121ba3c9ed0', 2, 'pathType has no effect on matching; it''s purely cosmetic metadata');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3ebf4f9-5576-41e8-b704-c88ad79a16f3', '376698cd-9fad-48ba-8517-9121ba3c9ed0', 3, 'Prefix restricts matching to HTTPS requests only');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f18a75ad-da44-46dc-b4d0-42110b6b1ae9', 'af6c1659-c3bd-4b35-a9d4-1801de01df80', 0, 'The Ingress controller''s default backend (or a defaultBackend field on an Ingress), which serves a fallback response (commonly a 404) for otherwise-unmatched requests');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('449251b3-a23d-4e90-8e84-f7625332cf27', 'af6c1659-c3bd-4b35-a9d4-1801de01df80', 1, 'The request is automatically routed to the first Service alphabetically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c07a303-2eec-4adc-a7a2-995e041f728a', 'af6c1659-c3bd-4b35-a9d4-1801de01df80', 2, 'The apiserver itself intercepts and answers the request');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b40a057f-fb2d-4bd8-b795-5e7950eed56e', 'af6c1659-c3bd-4b35-a9d4-1801de01df80', 3, 'The request is silently dropped and cannot generate a response');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84433cc5-3300-4c52-bbe4-78fe191a6df4', '957a9dae-81a4-4850-ba21-7f513144663e', 0, 'By referencing a Secret of type kubernetes.io/tls (containing tls.crt/tls.key) in the Ingress''s spec.tls block for that host — the Ingress controller uses it to terminate HTTPS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dec97e31-93fe-446c-88d5-1b4fd5711763', '957a9dae-81a4-4850-ba21-7f513144663e', 1, 'TLS termination is handled automatically without any Secret, purely from the Service''s port number');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8538fbdb-41a5-4bf2-9f2b-b5836354755e', '957a9dae-81a4-4850-ba21-7f513144663e', 2, 'By setting a NetworkPolicy that allows port 443');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf8edccb-6ac7-4c51-9878-2af14173cfa0', '957a9dae-81a4-4850-ba21-7f513144663e', 3, 'Ingress resources cannot terminate TLS; that always has to happen at the Service');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12e1a0b5-37c3-4af1-b602-73939d87b435', '71be5704-485a-4354-9e1a-b9f95bcf96fe', 0, 'Via spec.ingressClassName, referencing the name of an IngressClass object associated with the desired controller');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c100f4a8-47fd-4e75-b005-fe2a5f3e01d5', '71be5704-485a-4354-9e1a-b9f95bcf96fe', 1, 'Via the Service''s type field');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0144b229-0d4b-4131-8901-c15c61095957', '71be5704-485a-4354-9e1a-b9f95bcf96fe', 2, 'Ingress resources are always handled by every installed controller simultaneously');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa8f7965-c9d6-4c41-9360-8dcd910be4fd', '71be5704-485a-4354-9e1a-b9f95bcf96fe', 3, 'By naming the Ingress resource identically to the controller''s Deployment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3d04c3a-9e54-43d2-9fb4-cbc224d1b66c', '6a97e2c3-1b46-4a9e-83ef-e750f8ac2a62', 0, 'The Ingress objects are accepted and stored by the API server, but nothing actually implements the routing — no traffic is proxied per those rules until a controller is running');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f56834b-3a16-4de4-b8e0-24fd2fd1f081', '6a97e2c3-1b46-4a9e-83ef-e750f8ac2a62', 1, 'The API server rejects Ingress creation outright');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5eb6465b-e9fe-42ed-8794-53c8eac5e8b5', '6a97e2c3-1b46-4a9e-83ef-e750f8ac2a62', 2, 'Kubernetes automatically installs a default Ingress controller');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1d10d4d-034f-4c63-9b40-5cd3c14162c0', '6a97e2c3-1b46-4a9e-83ef-e750f8ac2a62', 3, 'The Ingress rules are silently converted into NodePort Services');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02f8eef4-fec8-434c-b55f-c73de728c487', 'ee4f453d-ea78-4758-856e-0fae93565c3f', 0, 'Ingress lets you consolidate host/path-based routing for many Services behind a single external entry point/IP, plus centralize concerns like TLS termination — rather than provisioning a separate external load balancer per Service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bb09516-5f15-4cb1-80b9-96ac27b016e6', 'ee4f453d-ea78-4758-856e-0fae93565c3f', 1, 'Ingress is required before a Service can have any Pods at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9eab9692-02ed-4b01-9cf6-3dd3a3c60225', 'ee4f453d-ea78-4758-856e-0fae93565c3f', 2, 'A Service can never receive external traffic without an Ingress');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b44f632b-56fe-4359-8ee3-8f03df82bd77', 'ee4f453d-ea78-4758-856e-0fae93565c3f', 3, 'Ingress replaces the need for Pod labels');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a68b72e-8312-448a-8cac-dd751f20b7c3', '314ae594-c13d-44da-8d30-4d126589d19d', 0, 'Controller-specific annotations on the Ingress object — these are implementation-specific extensions, not portable across different Ingress controllers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b150179e-7fc4-4b15-93bf-cc419fd39783', '314ae594-c13d-44da-8d30-4d126589d19d', 1, 'A required field called spec.rewriteRules present on every Ingress');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('155ecf5f-1f86-4d29-b376-7a705950ebb9', '314ae594-c13d-44da-8d30-4d126589d19d', 2, 'A separate CRD that must be manually installed for every annotation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea76201d-aa9a-4d55-a3ad-0306d9491226', '314ae594-c13d-44da-8d30-4d126589d19d', 3, 'Environment variables set on the Ingress controller''s own Pods only');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2193266-fea9-4ff3-941c-e2da6444ecf1', '7fba88a9-2ef8-4c0b-bcca-bf8bc3e1adb7', 0, 'The behavior is undefined/controller-specific — most controllers pick one deterministically (e.g. oldest resource), but this is a misconfiguration you should avoid rather than rely on');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('337c7bfd-e069-4262-ae03-41ac8b5477fe', '7fba88a9-2ef8-4c0b-bcca-bf8bc3e1adb7', 1, 'Kubernetes automatically load-balances 50/50 between both backend Services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c27f523a-7f18-487a-ae66-d4964f72f831', '7fba88a9-2ef8-4c0b-bcca-bf8bc3e1adb7', 2, 'The API server rejects the second Ingress at creation time in every case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7161d6f-ac71-4cf8-ade3-c08af705430a', '7fba88a9-2ef8-4c0b-bcca-bf8bc3e1adb7', 3, 'Both rules are always merged into a single route with no ambiguity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f44a4387-4012-4bd4-9911-fdc7d22e41bf', '851d0d38-480f-4b4a-9c2c-1a7bc00e8e0b', 0, 'Not by itself — the Ingress resource just declares routing rules; an actual Ingress controller (running as Pods, typically fronted by a LoadBalancer or NodePort Service) must be deployed and watching for it to take effect');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b7ab976-07ff-45da-9780-1768acf1b965', '851d0d38-480f-4b4a-9c2c-1a7bc00e8e0b', 1, 'Yes, Ingress objects always provision their own dedicated external IP automatically with zero other components needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc13035c-4e6c-476c-8d9c-c3eacb195ec5', '851d0d38-480f-4b4a-9c2c-1a7bc00e8e0b', 2, 'No — Ingress can only route traffic that originates inside the cluster');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b95f9e80-dd5a-4425-a4f3-a56fa9be86d5', '851d0d38-480f-4b4a-9c2c-1a7bc00e8e0b', 3, 'Yes, but only for gRPC traffic');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('832d6a68-c054-4b15-9f3b-91eb8c13258f', 'e9c59080-5f05-43f6-a8c9-906038e7ff20', 0, 'If policyTypes isn''t set explicitly, Kubernetes infers it from which of ingress/egress blocks are present — but it''s best practice to set it explicitly, since relying on inference can produce a policy that doesn''t restrict the traffic direction you intended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccf23c4d-b105-4b90-b7b4-76c708354719', 'e9c59080-5f05-43f6-a8c9-906038e7ff20', 1, 'The NetworkPolicy is rejected by the API server for missing a required field');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52f14438-1442-49b3-ab5f-be54764e1527', 'e9c59080-5f05-43f6-a8c9-906038e7ff20', 2, 'policyTypes has no effect on behavior in any case; it''s purely documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3419d998-eb1f-4bea-99c3-600c54c4c3bf', 'e9c59080-5f05-43f6-a8c9-906038e7ff20', 3, 'Without policyTypes, the policy defaults to blocking all traffic in both directions regardless of the ingress/egress blocks present');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cd1b7b2-d1ae-4c75-9610-4a6b4cc75eac', '5900dc70-e941-4acf-b6fa-292dfec375aa', 0, 'spec.ingress[].from[].podSelector, matching on app: frontend, combined with spec.podSelector on the policy itself selecting app: checkout');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2190fff6-7483-4d72-bd76-7458e210e8aa', '5900dc70-e941-4acf-b6fa-292dfec375aa', 1, 'spec.egress[].to[].podSelector on a policy that selects app: frontend');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5dccdc0-6deb-4099-b561-d29406bafbf2', '5900dc70-e941-4acf-b6fa-292dfec375aa', 2, 'metadata.labels on the NetworkPolicy object itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('959568d6-2f4c-4ba9-aaa1-30921358f776', '5900dc70-e941-4acf-b6fa-292dfec375aa', 3, 'spec.serviceAccountName referencing the frontend Pods'' ServiceAccount');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83862497-d770-4df1-862a-9939781d9249', '516461c6-81ff-47e6-a6fa-91d0c5c6c09d', 0, 'Set policyTypes: [Egress] only (omitting Ingress), and include only an egress block — leaving Ingress out of policyTypes avoids also imposing a default-deny on inbound traffic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1771b1d1-8624-47c7-85b5-c5ca4eb519b3', '516461c6-81ff-47e6-a6fa-91d0c5c6c09d', 1, 'Set policyTypes: [Ingress, Egress] always, regardless of intent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35f0e5d6-ca24-4ba8-b187-151775feb609', '516461c6-81ff-47e6-a6fa-91d0c5c6c09d', 2, 'NetworkPolicy cannot restrict egress traffic under any circumstances — only ingress');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fbd21e4-8a9d-4d2c-89a5-065618884cef', '516461c6-81ff-47e6-a6fa-91d0c5c6c09d', 3, 'Add an ingress rule with an empty ''from'' to explicitly allow all inbound');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d0dee412-70ee-44e4-b1c8-7fe6b3a6f6bf', 'e22223b3-d798-4314-9abc-1c7970bc6f37', 0, 'Only traffic matching that specific protocol/port combination is allowed by that rule, even if the ''from'' peer selector otherwise matches — other ports to the same Pods remain governed by whatever other rules (or the default) apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb8aa942-aa50-4b7e-8f46-12f540636c22', 'e22223b3-d798-4314-9abc-1c7970bc6f37', 1, 'The port field is ignored; NetworkPolicy can only filter by IP/label, never by port');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d236784e-3d05-4366-9d42-a61257db2fb2', 'e22223b3-d798-4314-9abc-1c7970bc6f37', 2, 'It opens all ports on the selected Pods once any port is listed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25119dc1-8b53-402f-9d8b-60668ee7e471', 'e22223b3-d798-4314-9abc-1c7970bc6f37', 3, 'It applies only to UDP traffic on that port, never TCP');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65158623-8330-4e00-b973-d4b9ee333b77', '4ac926a3-aeab-47a5-ab11-36101d125498', 0, 'Kubernetes itself doesn''t enforce NetworkPolicy — it''s up to the cluster''s CNI plugin to implement it (e.g. Calico, Cilium); if the installed CNI doesn''t support NetworkPolicy, the objects are accepted but have no actual effect');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47d4cb2d-ec22-469c-981f-a6bf48879ea1', '4ac926a3-aeab-47a5-ab11-36101d125498', 1, 'NetworkPolicy objects require a paid Kubernetes distribution to function at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19eef8d2-1d07-4123-aeb2-eb04e2263dcb', '4ac926a3-aeab-47a5-ab11-36101d125498', 2, 'NetworkPolicy only takes effect after a full cluster restart');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d591aff-6067-47cf-82b2-6400feefe488', '4ac926a3-aeab-47a5-ab11-36101d125498', 3, 'NetworkPolicy can only be created by a ClusterRole with wildcard permissions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d15fbd0-a886-43e4-9ead-8a6cbb779855', 'ad0819de-460b-4b5a-ad43-40eddd59d06b', 0, 'payments.billing.svc.cluster.local (with ''cluster.local'' being the default cluster domain, which can be configured differently in some clusters)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e37fd556-f750-416c-922e-760a7e008831', 'ad0819de-460b-4b5a-ad43-40eddd59d06b', 1, 'payments.billing.pod.local');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('207a2f8d-1fbd-4ca2-90e7-4252825ab871', 'ad0819de-460b-4b5a-ad43-40eddd59d06b', 2, 'svc.billing.payments.cluster');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a39fea76-52fc-4a73-92cf-fbda281825eb', 'ad0819de-460b-4b5a-ad43-40eddd59d06b', 3, 'billing-payments.svc');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10abd6c1-5b4c-4b81-89ac-1db2be4297b1', '8a6c8ff0-83ec-4d8c-9e5a-34e88273b856', 0, 'A bare Service name only resolves within its own namespace by default search-domain expansion; the caller must use the namespace-qualified name payments.billing (or the full FQDN) to resolve across namespaces');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7de20e12-547a-4e4b-bf97-7c3ef40aba66', '8a6c8ff0-83ec-4d8c-9e5a-34e88273b856', 1, 'Cross-namespace Service calls are blocked by Kubernetes unless a NetworkPolicy explicitly allows DNS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04e3e0e8-f284-4592-9f39-32221c545905', '8a6c8ff0-83ec-4d8c-9e5a-34e88273b856', 2, 'Service names are globally unique across namespaces, so ''payments'' alone should always work identically everywhere');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e330cc2-0d37-44b3-aca7-c657b8dbe39d', '8a6c8ff0-83ec-4d8c-9e5a-34e88273b856', 3, 'DNS only works within the default namespace; all others require an Ingress');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca3acbc8-0efc-4e38-98ed-9a072300bf4c', '822f61cb-3fd8-464e-996c-27bf8a78a422', 0, 'Via its stable per-Pod DNS record: <pod-name>.<headless-service-name>.<namespace>.svc.cluster.local (e.g. db-0.db.default.svc.cluster.local)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d916c4f3-ce77-4fad-a679-28317c4ed06e', '822f61cb-3fd8-464e-996c-27bf8a78a422', 1, 'By using the Pod''s ephemeral IP address only — no stable per-Pod DNS name exists');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62997ee9-fa66-4ee5-a9b3-2b5d811e6daf', '822f61cb-3fd8-464e-996c-27bf8a78a422', 2, 'By appending the Pod''s UID to the Service''s DNS name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abe46b85-afb9-4ca1-8644-e43dc40ac470', '822f61cb-3fd8-464e-996c-27bf8a78a422', 3, 'Individual Pods behind any Service are never individually addressable by DNS');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('465ed309-881b-4cee-848b-9a00d8b95529', '3844b815-7b8b-4268-bebc-cb276ad7198f', 0, 'dnsPolicy: ''None'' combined with an explicit dnsConfig block specifying nameservers/searches/options');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f3401b1-41b1-426b-a8ba-313380393c8e', '3844b815-7b8b-4268-bebc-cb276ad7198f', 1, 'Only an environment variable named DNS_SERVER, which Kubernetes reads automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44820e5c-8f91-40f7-88a1-aa95fef370de', '3844b815-7b8b-4268-bebc-cb276ad7198f', 2, 'This isn''t configurable per-Pod; it requires changing the cluster''s CoreDNS ConfigMap for every Pod cluster-wide');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f83a6ab1-77f2-4eca-adbd-acae1101d6bc', '3844b815-7b8b-4268-bebc-cb276ad7198f', 3, 'securityContext.dnsCapabilities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('886de66e-3a04-4412-b9ca-1ad329035d2a', '4eb138dc-c06f-45d0-b22d-66e27a76e032', 0, 'They share the same network namespace (and thus the same Pod IP), so one container can reach the other via localhost:<port> — no Service or DNS lookup is needed between containers in the same Pod');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('665592a8-6964-4437-b602-038deb18fcb6', '4eb138dc-c06f-45d0-b22d-66e27a76e032', 1, 'They must use the Pod''s Service DNS name to reach each other, exactly as an external client would');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61f07a14-7396-477a-bba4-d23441fdccf9', '4eb138dc-c06f-45d0-b22d-66e27a76e032', 2, 'They can only communicate via a shared volume, never over the network');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1dd52bfe-6d21-4dda-88ea-0895e6a308f2', '4eb138dc-c06f-45d0-b22d-66e27a76e032', 3, 'Each container in a Pod gets its own separate IP address');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3795e227-f693-4ef7-b889-3df9f90622e5', '0e489542-2a3a-4ccf-983b-9f539dd02e9f', 0, 'This causes a real conflict, since containers in a Pod share one network namespace/IP — only one process can actually bind port 8080 at a time; the second container''s listener will fail to bind');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14713916-2524-468f-a6a8-36e9546b6a95', '0e489542-2a3a-4ccf-983b-9f539dd02e9f', 1, 'Kubernetes automatically remaps one of them to a different port transparently');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe7dd8e5-a500-443e-9f39-2a3d58015c54', '0e489542-2a3a-4ccf-983b-9f539dd02e9f', 2, 'Each container gets an isolated view of port 8080, so there''s no conflict');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f129a554-5b52-49e0-8c2d-7bb125c35b02', '0e489542-2a3a-4ccf-983b-9f539dd02e9f', 3, 'This is only a problem if a Service also targets port 8080');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1d7782d-ee50-44d9-8c3c-3e9447acaf59', '456acb9b-abd8-4221-bb1e-b527f0801871', 0, 'Connect to localhost:8080 (or 127.0.0.1:8080), since both containers share the Pod''s network namespace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('51130d39-fbad-4d3f-96a4-520d43f8e160', '456acb9b-abd8-4221-bb1e-b527f0801871', 1, 'Look up the main container by its container name via cluster DNS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62a76e51-6ee5-41f6-a2fd-006022ce4ae9', '456acb9b-abd8-4221-bb1e-b527f0801871', 2, 'Create a dedicated ClusterIP Service just for intra-Pod communication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a04fa864-88c5-4c71-bf64-24448e280d43', '456acb9b-abd8-4221-bb1e-b527f0801871', 3, 'Use the Pod''s external LoadBalancer IP');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76c4d417-82e0-478c-800b-02ecd7c1a084', '951271b2-0d68-4403-99f8-d2aafdb0bdae', 0, 'A NetworkPolicy selecting your Pods (via podSelector) with an ingress rule explicitly allowing traffic from the specific caller Pods/namespaces you expect — default-deny means nothing gets in until you say so');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d29039a-e414-40fe-a7fb-88dbaea0202c', '951271b2-0d68-4403-99f8-d2aafdb0bdae', 1, 'Nothing — default-deny only applies to egress, never ingress, so your Service works immediately');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ddd5565-a314-4cee-b903-33deba420974', '951271b2-0d68-4403-99f8-d2aafdb0bdae', 2, 'Change your Service''s type to LoadBalancer to bypass NetworkPolicy entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8084b56b-53d9-4217-9f1e-7bdc43a02b4c', '951271b2-0d68-4403-99f8-d2aafdb0bdae', 3, 'Disable NetworkPolicy enforcement cluster-wide from within your own namespace''s manifests');
